/* ===================== Ảnh nhân vật (dữ liệu nhúng + hỗ trợ điểm gắn) =====================
   Nguồn dữ liệu: assets/charimages.js (sinh từ thư mục làm việc cropped/)
   Mục đích: avatar ảnh tròn bong bóng nổi / guide dải ngang trang hướng dẫn / empty dải ngang trạng thái trống / card ảnh bìa thẻ / portrait chân dung hồ sơ
   Tắt: khi thiết lập charImageOff = true thì ẩn toàn bộ
======================================================================== */
function cdCharImgUrl(use) {
  try {
    var s = (typeof cdGetSettings === 'function') ? cdGetSettings() : {};
    if (s.charImageOff === true) return '';
    var id = s.charImage || 'levi-mochizuki';
    var lib = (typeof CD_CHAR_IMAGES !== 'undefined') ? CD_CHAR_IMAGES : null;
    if (!lib) return '';
    var m = lib[id] || lib['levi-mochizuki'];
    return m ? (m[use] || '') : '';
  } catch (e) { return ''; }
}
/** Sinh thuộc tính style (dùng cho template string): có ảnh thì kèm background-image */
function cdCharArtAttr(use) {
  var u = cdCharImgUrl(use);
  return u ? ' style="background-image:url(&quot;' + u + '&quot;)"' : '';
}
/** Hero trang hướng dẫn: có ảnh thì thêm class cdb-hero-img (CSS lo lớp phủ và bố cục) */
function cdCharHeroCls() { return cdCharImgUrl('guide') ? ' cdb-hero-img' : ''; }
function cdCharHeroAttr() { return cdCharArtAttr('guide'); }
/** Trạng thái trống: có ảnh thì thêm class cd-empty-art (CSS lo dải minh họa phía trên) */
function cdCharEmptyCls() { return cdCharImgUrl('empty') ? ' cd-empty-art' : ''; }
function cdCharEmptyAttr() { return cdCharArtAttr('empty'); }
/** Avatar bong bóng nổi: gắn ảnh avatar lên .cd-fab-orb, có ảnh thì ẩn icon quyển sách */
function cdApplyFabOrb() {
  try {
    var fab = document.getElementById(FAB_ID);
    if (!fab) return;
    var btn = fab.querySelector('.cd-fab-btn');
    if (!btn) return;
    var orb = btn.querySelector('.cd-fab-orb');
    if (!orb) return;
    var u = cdCharImgUrl('avatar');
    orb.style.backgroundImage = u ? ('url("' + u + '")') : '';
    btn.classList.toggle('cd-has-orb', !!u);
  } catch (e) {}
}
/** Làm mới ảnh nhân vật trong panel (gọi sau khi đổi thiết lập): dán lại ảnh cho các điểm gắn đang hiển thị */
function cdRefreshCharArt() {
  try {
    cdApplyFabOrb();
    var hero = document.querySelector('.cdb-empty-guide-hero');
    if (hero) {
      var u = cdCharImgUrl('guide');
      hero.classList.toggle('cdb-hero-img', !!u);
      hero.style.backgroundImage = u ? ('url("' + u + '")') : '';
    }
    var em = document.querySelector('.cd-empty');
    if (em) {
      var ue = cdCharImgUrl('empty');
      em.classList.toggle('cd-empty-art', !!ue);
      em.style.backgroundImage = ue ? ('url("' + ue + '")') : '';
    }
  } catch (e) {}
}
