  liveLowerFields   : ['Sự việc đã trải qua', 'Vật phẩm sở hữu', 'Nhiệm vụ'],        // Trường lý lịch (tùy chỉnh thêm/xóa/sửa được)
  liveTableMode     : 'auto',    // Chế độ kích hoạt điền bảng: 'auto' (tự động ở cuối chính văn) | 'batch' (gom mỗi N tầng)
  liveTableBatch    : 1,         // Gom theo N tầng: mỗi N tầng điền một lần (1 = tầng nào cũng điền)
  liveTableBatchSource : 'tavern', // Nguồn API cho chế độ gom: 'tavern' (theo Tavern) hoặc openai/claude/gemini
