// Nhật ký debug
function cdLog(...args) {
  if (DEBUG) console.log('[CD]', ...args);
}
function cdWarn(...args) {
  if (DEBUG) console.warn('[CD]', ...args);
}
// ============================================================
// Plugin Nhật ký nhân vật v2.0.0 — tầng gọi API
// Đường dẫn: SillyTavern/extensions/character-diary/api.js
// ============================================================
'use strict';

/**
 * Lối vào thống nhất: định tuyến tới phần triển khai API tương ứng theo settings.source
 * @param {Array<{role:string,content:string}>} messages
 * @param {object} s - settings
 * @returns {Promise<string>} văn bản AI trả về
 */
/**
 * Gọi LLM API, trả về { text, elapsed, tokenUsage }
 * @returns {Promise<{text:string, elapsed:number, tokenUsage:object|null}>}
 */
async function cdApiComplete(messages, s) {
  const start = Date.now();
  let text;
  // Ưu tiên nguồn do người dùng cấu hình rõ ràng, nếu không thì suy ra từ các endpoint đã cấu hình; không có gì thì dùng Tavern
  // ★ Tôn trọng rõ ràng lựa chọn của người dùng: không còn kiểu “chưa điền địa chỉ thì lặng lẽ chuyển sang kết nối chính của Tavern” (như vậy sẽ đốt hạn mức model chính)
  let effSrc = (s.source === 'openai' || s.source === 'claude' || s.source === 'gemini') ? s.source
             : (s.source === 'tavern' ? 'tavern' : null);
  const _hasEp = k => !!(s.endpoints && s.endpoints[k] && s.endpoints[k].url);
  const _fbOn  = () => (s.allowTavernFallback === true);
  const _noFbErr = (m) => { const e = new Error(m); e.cdNoFallback = true; return e; };
  if (effSrc === null) {
    // Không chọn nguồn rõ ràng: suy ra theo endpoint đã cấu hình; không cấu hình cái nào mới dùng Tavern (lúc này Tavern là kênh khả dụng duy nhất, không tính là hạ cấp)
    effSrc = _hasEp('openai') ? 'openai' : _hasEp('claude') ? 'claude' : _hasEp('gemini') ? 'gemini' : 'tavern';
  } else if (effSrc !== 'tavern' && !_hasEp(effSrc)) {
    // Đã chọn rõ nguồn kết nối trực tiếp mà không điền địa chỉ: mặc định từ chối lén chuyển sang kết nối chính của Tavern
    if (!_fbOn()) {
      throw _noFbErr('Nguồn API là “' + effSrc + '” nhưng chưa điền địa chỉ API: theo thiết lập đã từ chối tự động hạ cấp sang kênh Tavern (sẽ không tiêu tốn hạn mức model chính của Tavern).'
        + 'Hãy vào thiết lập điền địa chỉ API, hoặc bật “Cho phép hạ cấp sang kênh Tavern”, hoặc chọn rõ nguồn API là “Tavern hiện tại”.');
    }
    cdWarn('[API] Chưa cấu hình địa chỉ ' + effSrc + ', hạ cấp sang kênh Tavern theo thiết lập');
    if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] Chưa cấu hình địa chỉ ' + effSrc + ', đã hạ cấp sang kênh Tavern (bạn đã bật “Cho phép hạ cấp”)');
    effSrc = 'tavern';
  }
  switch (effSrc) {
    case 'tavern': text = await callTavern(messages, s); break;
    case 'openai': text = await callOpenAI(messages, s.endpoints.openai, s); break;
    case 'claude': text = await callClaude(messages, s.endpoints.claude, s); break;
    case 'gemini': text = await callGemini(messages, s.endpoints.gemini, s); break;
    default: throw new Error('Nguồn API không xác định: ' + effSrc);
  }
  const elapsed = Date.now() - start;
  // Đọc lượng token có thể đã được ghi trong callXxx
  const tokenUsage = _cdLastTokenUsage;
  _cdLastTokenUsage = null; // Dùng xong thì đặt lại
  return { text, elapsed, tokenUsage };
}

/** overrides prompt trần: chặn preset/thẻ nhân vật/sách thế giới/jailbreak/lịch sử chat của Tavern, chỉ gửi bản thân nội dung tóm tắt */
function cdBareOverrides() {
  return {
    char_description: '', char_personality: '', scenario: '',
    world_info_before: '', world_info_after: '', dialogue_examples: '',
    persona_description: '', jailbreak: '', system_prompt: '',
    chat_history: { with_depth_entries: false, prompts: [] },
  };
}

/** ★ FIX11: lấy đúng generateRaw
 *  Bản chính thức gắn nó lên SillyTavern.getContext() (không phải biến toàn cục),
 *  plugin trước đây dùng định danh trần `typeof generateRaw` để kiểm tra → luôn false → kênh sạch chưa từng được dùng.
 *  Ở đây lấy theo ba cấp ctx → toàn cục → import động('/script.js'), kết quả được cache. */
let _cdRawGenCache;   // undefined = chưa tra / null = tra rồi nhưng không lấy được / function = dùng được
async function cdGetRawGen(ctx) {
  if (_cdRawGenCache !== undefined) return _cdRawGenCache;
  let g = null;
  if (ctx && typeof ctx.generateRaw === 'function') {
    g = ctx.generateRaw;
  } else if (typeof generateRaw === 'function') {
    g = generateRaw;
  } else {
    // Dự phòng: import động script chính của Tavern (chính thức khuyên dùng '/script.js', vốn là module đã tải, không chạy lặp)
    const cands = ['/script.js', '../../../../script.js', '../../script.js'];
    for (let _i = 0; _i < cands.length; _i++) {
      try {
        const _m = await import(/* webpackIgnore: true */ cands[_i]);
        if (_m && typeof _m.generateRaw === 'function') { g = _m.generateRaw; break; }
      } catch (_e) { /* đổi sang đường dẫn ứng viên tiếp theo */ }
    }
  }
  _cdRawGenCache = g;
  return g;
}

/** Theo kết nối hiện tại của Tavern
 *  ★ FIX11: mỗi lần gọi tối đa chỉ gửi một request thật.
 *    Cách cũ mỗi kênh đều là `if (result) return result;`, trả về rỗng (falsy) thì đi tiếp xuống
 *    kênh sau gửi thêm một request thật nữa → một lần tóm tắt có thể gửi liền tới 3 lần, và kênh ở giữa
 *    generateQuietPrompt sẽ mang theo toàn bộ lịch sử chat/thẻ nhân vật/preset/sách thế giới. */
async function callTavern(messages, _s) {
  const ctx = SillyTavern.getContext();
  const ordered = messages.map(m => ({ role: m.role, content: m.content }));
  // ★ Prompt trần nghiêm ngặt (mặc định bật): chỉ gửi bản thân nội dung tóm tắt cho model, không kèm preset/thẻ nhân vật/sách thế giới/jailbreak của Tavern
  const bare = !(_s && _s.strictPrompt === false);
  const ov = bare ? cdBareOverrides() : undefined;
  const _tag = bare ? '(đã chặn preset/thẻ nhân vật/sách thế giới/lịch sử chat)' : '(chưa chặn preset)';
  const _lg = (m, lv) => { try { if (typeof cdAddLog === 'function') cdAddLog(lv || 'api_req', m); } catch (e) {} };

  // Kênh ① generateRaw —— kênh sạch duy nhất thực sự “không có ngữ cảnh chat + chặn được preset”
  const rawGen = await cdGetRawGen(ctx);
  if (rawGen) {
    try {
      const args = { ordered_prompts: ordered, should_stream: false };
      if (ov) args.overrides = ov;
      const result = await rawGen(args);
      _lg('[API] Kênh ① generateRaw' + _tag);
      // ★ Request đã thực sự gửi đi và nhận được phản hồi: dù nội dung có rỗng hay không cũng dừng tại đây, tuyệt đối không thử kênh khác
      return String(result == null ? '' : result);
    } catch (e) {
      cdWarn('generateRaw thất bại', e);
      _lg('[API] Kênh ① generateRaw ném lỗi: ' + ((e && e.message) || e), 'warn');
    }
  } else {
    _lg('[API] Không lấy được generateRaw, chuyển sang sendGenerationRequest (cũng chặn được preset)', 'warn');
    cdWarn('Không lấy được generateRaw (đã thử ctx / toàn cục / import động)');
  }

  // Kênh ② sendGenerationRequest —— tạo ngầm tiêu chuẩn của ST, hỗ trợ overrides
  if (ctx && typeof ctx.sendGenerationRequest === 'function') {
    try {
      const _p = { quiet_prompt: ordered.map(m => m.content).join('\n\n'), execute_senders: false };
      if (ov) _p.overrides = ov;
      const result = await ctx.sendGenerationRequest(_p);
      _lg('[API] Kênh ② sendGenerationRequest' + _tag);
      return String(result == null ? '' : result);
    } catch (e) {
      cdWarn('sendGenerationRequest thất bại', e);
      _lg('[API] Kênh ② sendGenerationRequest ném lỗi: ' + ((e && e.message) || e), 'warn');
    }
  }

  // Kênh ③ generateQuietPrompt —— ngữ nghĩa chính thức là “thêm prompt ngầm vào ngữ cảnh chat”,
  //   ắt mang theo lịch sử chat + thẻ nhân vật + preset + sách thế giới, và nó không nhận overrides, không thể chặn.
  //   ★ Khi bật prompt trần nghiêm ngặt thì vô hiệu nó (nếu không vừa đốt hạn mức vừa làm bẩn kết quả), báo lỗi luôn để người dùng biết.
  if (ctx && typeof ctx.generateQuietPrompt === 'function') {
    if (bare) {
      const _m = 'Đã bật prompt trần nghiêm ngặt, nhưng Tavern hiện tại chỉ cung cấp generateQuietPrompt (ắt mang theo lịch sử chat/thẻ nhân vật/preset/sách thế giới, và không thể chặn). '
        + 'Để tránh đốt hạn mức vô ích và làm bẩn kết quả tóm tắt, request lần này đã bị hủy. Hãy chuyển sang nguồn API kết nối trực tiếp, hoặc tắt “Prompt trần nghiêm ngặt”.';
      _lg('[API] ' + _m, 'error');
      throw new Error(_m);
    }
    try {
      const result = await ctx.generateQuietPrompt({ quietPrompt: ordered.map(m => m.content).join('\n\n') });
      _lg('[API] Kênh ③ generateQuietPrompt (chưa chặn preset/lịch sử chat, vì bạn đã tắt prompt trần nghiêm ngặt)', 'warn');
      return String(result == null ? '' : result);
    } catch (e) { cdWarn('generateQuietPrompt thất bại', e); }
  }

  // Kênh ④ dự phòng bằng hàm generate toàn cục của phiên bản cũ
  if (typeof generate === 'function') {
    const _g = Object.assign({
      user_input: ordered.map(m => m.content).join('\n\n'),
      should_stream: false,
      overrides: {
        char_description: '', char_personality: '', scenario: '',
        world_info_before: '', world_info_after: '', dialogue_examples: '',
        chat_history: { with_depth_entries: false, prompts: [] },
      },
    }, bare ? { overrides: cdBareOverrides() } : {});
    const result = await generate(_g);
    _lg('[API] Kênh ④ generate' + _tag);
    return String(result == null ? '' : result);
  }

  throw new Error('Không có cách tạo LLM khả dụng (đã thử generateRaw / sendGenerationRequest / generateQuietPrompt / generate)');
}


async function callOpenAI(messages, ep, s) {
  const base = String(ep.url || '').replace(/\/+$/, '');
  if (!base) throw new Error('OpenAI chưa cấu hình địa chỉ API');
  // ★ Gateway tương thích · đi qua proxy backend: khi bật “Kết nối qua proxy backend”, ưu tiên mượn kênh backend của Tavern
  //   (generateRaw / sendGenerationRequest) để chuyển tiếp, vượt qua chặn CORS/preflight của trình duyệt (một số gateway fetch từ front-end chắc chắn thất bại).
  //   Model lấy theo gateway người dùng điền; nếu kết nối hiện tại của Tavern đã cấu hình là nguồn tương thích đó thì ngữ nghĩa tương đương, không lẫn model chính.
  if (s.backendProxy) {
    try {
      const bp = await callTavern(messages, s);
      if (bp) return bp;
    } catch (e1) {
      cdWarn('Thử proxy backend (kênh Tavern) thất bại, quay lại kết nối trực tiếp: ' + (e1 && e1.message));
    }
  }
  // ★ Hạ cấp thông minh (phương án A, v2.6.3): server của các gateway như opencode.ai không trả header CORS,
  //   fetch trực tiếp từ front-end của trình duyệt/Tauri WebView sẽ ném "Failed to fetch" (TypeError: Failed to fetch).
  //   Lúc này tự động hạ cấp sang kênh Tavern (generateRaw / generateQuietPrompt) —— Tavern đi qua proxy phía server,
  //   không bị giới hạn CORS; và kết nối chính của Tavern thường cũng là cùng gateway, ngữ nghĩa tương đương.
  try {
    const res = await fetch(`${base}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${ep.key}` },
      body: JSON.stringify({ model: ep.model, messages: messages.map(function (_mm0) {
        var _rp0 = _cdParseMsgContent(_mm0.content);
        if (_rp0.images.length) {
          var _carr0 = [];
          if (_rp0.text) _carr0.push({ type: 'text', text: _rp0.text });
          _rp0.images.forEach(function (_d0) { _carr0.push({ type: 'image_url', image_url: { url: _d0 } }); });
          return { role: _mm0.role, content: _carr0 };
        }
        return { role: _mm0.role, content: _mm0.content };
      }), temperature: s.temperature, max_tokens: 8192, stream: false }),
    });
    if (!res.ok) {
      // 4xx/5xx là vấn đề của API hoặc khóa, không hạ cấp (tránh che giấu lỗi thật)
      throw new Error(`OpenAI ${res.status}: ${await textOr(res)}`);
    }
    const j = await res.json();
    // Ghi lượng token dùng vào biến toàn cục, để cdApiComplete trả về
    if (j.usage) {
      // Thống kê token chung
      const usage = { prompt: j.usage.prompt_tokens || 0, completion: j.usage.completion_tokens || 0, total: j.usage.total_tokens || 0 };
      // Thống kê cache DeepSeek (prompt_tokens_details / prompt_cache_*)
      usage.cacheHit = j.usage.prompt_cache_hit_tokens || j.usage.prompt_tokens_details?.cached_tokens || 0;
      usage.cacheMiss = j.usage.prompt_cache_miss_tokens || j.usage.prompt_tokens_details?.uncached_tokens || 0;
      _cdLastTokenUsage = usage;
    }
    // ★ Tương thích model suy luận: một số model (reasoning/DeepSeek-R1...) đặt chính văn ở reasoning_content còn content rỗng, cần lấy dự phòng
    var _msg0 = j.choices && j.choices[0] ? (j.choices[0].message || {}) : {};
    var _txt0 = _msg0.content || _msg0.reasoning_content || _msg0.delta || '';
    if (!_txt0 && j.choices && j.choices[0] && typeof j.choices[0].text !== 'undefined') _txt0 = j.choices[0].text;
    if (!_txt0 && Array.isArray(j.choices)) {
      var _all = j.choices.map(function(c){ var m=c&&c.message||{}; return m.content||m.reasoning_content||''; }).filter(Boolean).join('');
      if (_all) _txt0 = _all;
    }
    return String(_txt0 || '');
  } catch (e) {
    // Chỉ hạ cấp với “lỗi kiểu mạng/CORS” (Failed to fetch, TypeError, Level 2 CORS);
    // Lỗi nghiệp vụ 4xx/5xx rõ ràng thì không hạ cấp
    const msg = String(e && e.message || e);
    const isNetFail = /failed to fetch|networkerror|typeerror|load failed|not allowed to request|cors|connection/i.test(msg);
    if (isNetFail) {
      // ★ Mặc định không còn lặng lẽ hạ cấp sang kênh Tavern (sẽ dùng model chính đốt hạn mức). Cần thì bật rõ “Cho phép hạ cấp sang kênh Tavern”.
      if (s.allowTavernFallback !== true) {
        const _e2 = new Error('OpenAI kết nối trực tiếp thất bại (' + msg + '): theo thiết lập đã từ chối tự động hạ cấp sang kênh Tavern, không tiêu tốn hạn mức model chính của Tavern. '
          + 'Hãy kiểm tra địa chỉ API/khóa/CORS, hoặc bật “Cho phép hạ cấp sang kênh Tavern” trong thiết lập.');
        _e2.cdNoFallback = true;
        throw _e2;
      }
      cdWarn('OpenAI kết nối trực tiếp thất bại (đa phần do CORS), hạ cấp sang kênh Tavern: ' + msg);
      if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] OpenAI kết nối trực tiếp thất bại, tự động hạ cấp sang kênh Tavern', { err: msg });
      try {
        const text = await callTavern(messages, s);
        if (text) return text;
      } catch (e2) {
        cdWarn('Hạ cấp sang kênh Tavern cũng thất bại: ' + (e2 && e2.message));
      }
    }
    throw e; // Các lỗi khác ném ra nguyên trạng
  }
}

/**
 * Rerank xếp hạng lại (tương thích OpenAI /rerank, đường lui /v1/rerank)
 * @param {string} query văn bản truy vấn
 * @param {Array} documents mảng văn bản cần xếp hạng lại
 * @param {object} cfg { base, key, model }
 * @returns {Promise<{index:number, score:number}[]>} kết quả sắp xếp theo điểm giảm dần
 */
async function cdRerank(query, documents, cfg) {
  if (!query || !Array.isArray(documents) || !documents.length) return [];
  const rawBase = String(cfg.base || '').replace(/\/+$/, '');
  const key = cfg.key || '';
  const model = cfg.model || '';
  if (!rawBase || !model) throw new Error('Rerank chưa cấu hình base/model');
  const body = { model, query, documents };
  const headers = { 'Content-Type': 'application/json' };
  if (key) headers.Authorization = `Bearer ${key}`;
  // base có thể có /v1 hoặc không, sinh các tổ hợp endpoint ứng viên: base/v1 có hay không + hậu tố /rerank /v1/rerank
  const bases = [rawBase];
  // Nếu base kết thúc bằng /v1 thì thử thêm bản bỏ /v1; nếu không có thì thử thêm bản bổ sung /v1
  const hasV1 = /\/v1$/.test(rawBase);
  const altBase = hasV1 ? rawBase.replace(/\/v1$/, '') : rawBase + '/v1';
  if (altBase !== rawBase) bases.push(altBase);
  const suffixes = ['/rerank', '/v1/rerank'];
  let lastErr = null;
  for (const b of bases) {
    for (const suffix of suffixes) {
      if (!cfg.__noDupCheck && /rerank$/.test(b) && suffix.startsWith('/')) continue; // tránh trường hợp b đã chứa rerank
      try {
        const res = await fetch(`${b}${suffix}`, { method: 'POST', headers, body: JSON.stringify(body) });
        if (!res.ok) { lastErr = new Error(`${b}${suffix} ${res.status}: ${await textOr(res)}`); continue; }
        const j = await res.json();
        const results = Array.isArray(j.results) ? j.results
          : (Array.isArray(j.data) ? j.data : null);
        if (!results) { lastErr = new Error(`${b}${suffix} định dạng trả về không có results`); continue; }
        return results
          .filter(r => r && typeof r.index === 'number')
          .map(r => ({ index: r.index, score: r.relevance_score ?? r.score ?? 0 }))
          .sort((a, b) => b.score - a.score);
      } catch (e) {
        lastErr = e;
      }
    }
  }
  throw lastErr || new Error('Gọi Rerank thất bại');
}

/**
 * Rerank xếp hạng lại các kết quả vector đã truy xuất (thất bại thì tự hạ cấp trả về kết quả gốc)
 * @param {string} query văn bản truy vấn
 * @param {Array} results kết quả truy xuất [{ text, ... }]
 * @param {object} s thiết lập (đọc rerankEnabled/rerankTarget/rerankApi)
 * @param {string} target luồng hiện tại 'story' | 'diary'
 * @returns {Promise<Array>} kết quả sau khi xếp hạng lại (cùng cấu trúc với tham số đầu vào)
 */
async function cdRerankResults(query, results, s, target) {
  try {
    if (!s?.rerankEnabled) return results;
    if (!results || !results.length) return results;
    // Khớp target: 'both' ăn tất, hoặc bằng target hiện tại
    const want = s.rerankTarget || 'both';
    if (want !== 'both' && want !== target) return results;
    // ★ FIX10: nhớ chỉ số gốc trước rồi mới lọc. Trước đây docs lọc bỏ văn bản rỗng, nhưng ri.index lại dùng để tra results chưa lọc,
    //   chỉ cần một mục văn bản rỗng là lệch toàn bộ —— truy xuất về lại là mục ký ức khác, chèn cho AI thành râu ông nọ cắm cằm bà kia.
    const kept = [];
    results.forEach(function (r, i) { if (r && r.text) kept.push({ r: r, i: i }); });
    const docs = kept.map(x => x.r.text);
    if (!docs.length) return results;
    const cfg = s.rerankApi || {};
    const idxArr = await cdRerank(query, docs, cfg);
    // Sắp xếp lại theo thứ tự rerank
    const ranked = idxArr.map(ri => (kept[ri.index] ? kept[ri.index].r : null)).filter(Boolean);
    if (ranked.length) return ranked;
  } catch (e) {
    cdAddLog('warn', '[rerank] Xếp hạng lại thất bại, hạ cấp dùng kết quả gốc: ' + e.message);
  }
  return results;
}

/* Phân tích tin nhắn đa phương thức: tách đánh dấu [IMG]data:image/...[/IMG] trong content của tin nhắn thành mảng văn bản + ảnh */
function _cdParseMsgContent(content){
  var text=String(content||'');
  var images=[];
  var re=/\[IMG\](data:image\/[^\[\]]+)\[\/IMG\]/gi;
  var m;
  while((m=re.exec(text))){ images.push(m[1]); }
  text=text.replace(/\[IMG\](data:image\/[^\[\]]+)\[\/IMG\]/gi,'');
  text=text.replace(/\n{3,}/g,'\n\n').trim();
  return { text:text, images:images };
}

async function callClaude(messages, ep, s) {
  const base = ep.url.replace(/\/+$/, '');
  const system = messages.filter(m => m.role === 'system').map(m => m.content).join('\n\n');
  const msgs = messages.filter(m => m.role !== 'system').map(m => {
    var _rp = _cdParseMsgContent(m.content);
    if (_rp.images.length) {
      var _carr = [];
      if (_rp.text) _carr.push({ type: 'text', text: _rp.text });
      _rp.images.forEach(function (d) {
        var _mm = /^data:(image\/(?:png|jpeg|gif|webp));base64,(.*)$/.exec(d);
        if (_mm) _carr.push({ type: 'image', source: { type: 'base64', media_type: _mm[1], data: _mm[2] } });
      });
      return { role: m.role === 'assistant' ? 'assistant' : 'user', content: _carr };
    }
    return { role: m.role === 'assistant' ? 'assistant' : 'user', content: m.content };
  });
  const res = await fetch(`${base}/messages`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'x-api-key': ep.key, 'anthropic-version': '2023-06-01' },
    body: JSON.stringify({ model: ep.model, system, messages: msgs, max_tokens: 8192, temperature: s.temperature }),
  });
  if (!res.ok) throw new Error(`Claude ${res.status}: ${await textOr(res)}`);
  const j = await res.json();
  if (j.usage) {
    _cdLastTokenUsage = { prompt: j.usage.input_tokens, completion: j.usage.output_tokens, total: j.usage.input_tokens + j.usage.output_tokens };
  }
  return (j.content || []).map(p => p.text || '').join('');
}

async function callGemini(messages, ep, s) {
  const base = ep.url.replace(/\/+$/, '');
  const system = messages.filter(m => m.role === 'system').map(m => m.content).join('\n\n');
  const contents = messages.filter(m => m.role !== 'system').map(m => {
    var _rp = _cdParseMsgContent(m.content);
    var _parts = [];
    if (_rp.text) _parts.push({ text: _rp.text });
    _rp.images.forEach(function (d) {
      var _mm = /^data:(image\/[a-zA-Z0-9.+-]+);base64,(.*)$/.exec(d);
      if (_mm) _parts.push({ inline_data: { mime_type: _mm[1], data: _mm[2] } });
    });
    return { role: m.role === 'assistant' ? 'model' : 'user', parts: _parts };
  });
  const body = {
    contents,
    generationConfig: { temperature: s.temperature, maxOutputTokens: 8192 },
    safetySettings: [
      { category: 'HARM_CATEGORY_HARASSMENT',        threshold: 'BLOCK_NONE' },
      { category: 'HARM_CATEGORY_HATE_SPEECH',       threshold: 'BLOCK_NONE' },
      { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_NONE' },
      { category: 'HARM_CATEGORY_DANGEROUS_CONTENT',  threshold: 'BLOCK_NONE' },
    ],
  };
  if (system) body.systemInstruction = { parts: [{ text: system }] };
  const url = `${base}/models/${encodeURIComponent(ep.model)}:generateContent?key=${encodeURIComponent(ep.key)}`;
  const res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  if (!res.ok) throw new Error(`Gemini ${res.status}: ${await textOr(res)}`);
  const j = await res.json();
  var _gparts = (j.candidates && j.candidates[0] && j.candidates[0].content && j.candidates[0].content.parts) || [];
  var _gTxt = _gparts.map(p => p.text || '').join('');
  if (!_gTxt && j.candidates && j.candidates[0]) {
    // Model suy luận có thể đặt nội dung ở thoughts/reasoning, hoặc trong parts thiếu text
    var _gC = j.candidates[0];
    if (_gC.thoughts && Array.isArray(_gC.thoughts)) _gTxt = _gC.thoughts.map(function(t){ return t&&t.content||''; }).filter(Boolean).join('');
    if (!_gTxt && _gC.content && Array.isArray(_gC.content.parts)) {
      _gTxt = _gC.content.parts.map(function(p){ if(!p) return ''; return p.text||p.inline_data||''; }).filter(function(x){return typeof x==='string' && x;}).join('');
    }
  }
  return String(_gTxt || '');
}

/** Lấy danh sách model (dùng khi không phải API của Tavern) */
async function cdFetchModels(source, ep) {
  // ★ Tương thích nhiều tổ hợp endpoint URL có/không có /v1 (một số gateway chỉ mở /models dưới /v1)
  const rawBase = String(ep.url || '').replace(/\/+$/, '');
  const bases = [rawBase];
  try {
    const hasV1 = /\/v1$/.test(rawBase);
    const altBase = hasV1 ? rawBase.replace(/\/v1$/, '') : rawBase + '/v1';
    if (altBase && altBase !== rawBase) bases.push(altBase);
  } catch (e) {}
  const tryFetch = async (url, o) => {
    const r = await fetch(url, o);
    return await r.json();
  };
  const lastErr = [];
  for (const base of bases) {
    if (!base) continue;
    try {
      if (source === 'openai') {
        const j = await tryFetch(`${base}/models`, { headers: { Authorization: `Bearer ${ep.key}` } });
        const arr = (j.data || []).map(m => m && m.id).filter(Boolean);
        if (arr.length) return arr;
        lastErr.push(`${base}/models: trả về data rỗng`);
      }
      if (source === 'claude') {
        const j = await tryFetch(`${base}/models`, { headers: { 'x-api-key': ep.key, 'anthropic-version': '2023-06-01' } });
        const arr = (j.data || []).map(m => m && m.id).filter(Boolean);
        if (arr.length) return arr;
        lastErr.push(`${base}/models: trả về data rỗng`);
      }
      if (source === 'gemini') {
        const j = await tryFetch(`${base}/models?key=${encodeURIComponent(ep.key)}`);
        const arr = (j.models || []).map(m => (m.name || '').replace(/^models\//, '')).filter(Boolean);
        if (arr.length) return arr;
        lastErr.push(`${base}/models: trả về models rỗng`);
      }
    } catch (e) {
      lastErr.push(`${base} request thất bại:${e.message}`);
    }
  }
  // ★ Khi lấy trực tiếp thất bại (đa phần bị CORS front-end chặn), khớp danh sách dự phòng tích hợp theo tên miền gateway
  //   Chỉ điền lại các model “đã thử thực tế dùng được trên gateway đó”, tuyệt đối không nhét available_models của model chính Tavern (thường là gpt không liên quan...) vào.
  try {
    const host = (rawBase.toLowerCase());
    let kbModels = [];
    for (const key of Object.keys(CD_GATEWAY_MODELS)) {
      if (host.includes(key)) { kbModels = CD_GATEWAY_MODELS[key].filter(Boolean); break; }
    }
    if (kbModels && kbModels.length) {
      cdWarn('Lấy model trực tiếp thất bại (đa phần do CORS), đã khớp “danh sách dự phòng gateway tích hợp” và trả về model khả dụng');
      if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] Lấy model trực tiếp thất bại, dùng danh sách dự phòng gateway tích hợp', { source: source, host: host, count: kbModels.length });
      return kbModels;
    }
  } catch (e) {}
  // ★ Chỉ khi người dùng dùng nguồn “Tavern hiện tại (tavern)” mới đọc danh sách model dự phòng từ thiết lập OpenAI mà Tavern đã tải;
  //   đã điền gateway riêng (openai/claude/gemini) thì không đọc danh sách model chính của Tavern nữa, tránh trả về model không liên quan làm kết quả.
  if (source === 'tavern') {
    try {
      const oai = (typeof oai_settings !== 'undefined') ? oai_settings : (SillyTavern && SillyTavern.getContext() && SillyTavern.getContext().extensionSettings ? null : null);
      let fromTavern = [];
      if (oai) {
        const cand = [oai.available_models, oai.models, oai.custom_models, (oai.available_models && oai.available_models[oai.chat_completion_source])];
        for (const c of cand) {
          if (Array.isArray(c) && c.length) {
            fromTavern = c.map(m => (typeof m === 'string' ? m : (m && (m.id || m.name)))).filter(Boolean);
            if (fromTavern.length) break;
          }
        }
      }
      if (fromTavern.length) {
        cdWarn('Lấy model trực tiếp thất bại (đa phần do CORS), đã đọc danh sách model từ thiết lập Tavern đã tải');
        if (typeof cdAddLog === 'function') cdAddLog('warn', '[API] Lấy model trực tiếp thất bại, hạ cấp đọc danh sách model của Tavern', { count: fromTavern.length });
        return fromTavern;
      }
    } catch (e) {}
  }
  toastr.warning('[Nhật ký nhân vật] Lấy danh sách model thất bại (nếu gateway API của bạn không hỗ trợ CORS, hãy chuyển sang nguồn “Tavern hiện tại” ở trên, hoặc tự điền tên model): ' + (lastErr.join(' | ') || 'Lỗi không xác định'));
  return [];
}

function textOr(res) { return res.text().then(t => t.slice(0, 200)); }// ============================================================
// Plugin Nhật ký nhân vật v2.0.0 — Prompt & phân tích JSON
// Đường dẫn: SillyTavern/extensions/character-diary/prompts.js
// ============================================================
'use strict';

/* ============================== Prompt: Nhật ký ============================== */
async function cdBuildDiaryPrompt(windowFloors, data, s) {
  const known = Object.keys(data.diaries).map(name => {
    const al = (data.aliases[name] || []);
    return al.length ? `${name}(bí danh:${al.join(', ')})` : name;
  });
  // ★ Mỗi nhân vật chèn nhiều mục lịch sử gần nhất (mặc định vectorTopK mục), tránh chỉ chèn mục mới nhất của mỗi nhân vật
  const memLimit = Math.max(1, parseInt(s.vectorTopK, 10) || 5);
  const memory = (s.summarizeInjectDiary ? Object.entries(data.diaries).map(([name, list]) => {
    if (!Array.isArray(list) || !list.length) return '';
    return list.slice(-memLimit).map(function (e) {
      return `【${name}】${e.date ? e.date : 'Tầng ' + e.turn + ''}: ${(e.entry || '').trim()}`;
    }).join('\n');
  }).filter(Boolean).join('\n') : '');
  // ★ Văn bản tầng đã qua lọc thẻ
  const tags = s.filterTags || [];
  const scene = windowFloors.map(m => `[#${m.message_id} ${m.name}] ${cdFilterTags(m.mes, tags)}`).join('\n\n');

  // ★ Bắt theo nhân vật xuất hiện (phương án B): regex bắt nhân vật xuất hiện từ cốt truyện, chỉ đẩy nhật ký gần đây của các nhân vật này (thay cho chèn toàn bộ)
  let diaryMemory = memory;
  if (s.diaryCharFilter) {
    try {
      const capt = cdCaptureCast(scene, data);
      if (capt && capt.length) {
        const limit = Math.max(1, parseInt(s.diaryCharLimit,10)||3);
        const lines = [];
        capt.forEach(function(role){
          const list = (data.diaries && Array.isArray(data.diaries[role])) ? data.diaries[role] : [];
          if (!list.length) return;
          list.slice(-limit).forEach(function(e){
            lines.push(`【${role}】${e.date ? e.date : 'Tầng '+(e.turn!=null?e.turn:'?')+''}: ${(e.entry||'').trim()}`);
          });
        });
        if (lines.length) diaryMemory = 'Nhật ký gần đây của nhân vật xuất hiện (trích theo nhân vật xuất hiện):\n' + lines.join('\n');
        else diaryMemory = memory;
      }
    } catch (e) { if (typeof cdWarn==='function') cdWarn('Bắt theo nhân vật xuất hiện thất bại', e); diaryMemory = memory; }
  }
  // ★ Chế độ vector hóa: truy xuất nhật ký lịch sử liên quan (ghi đè dropdown ký ức toàn bộ)
  if (s.diaryMode === 'vector') {
    try {
      if (Array.isArray(data.diaryVectors) && data.diaryVectors.length > 0) {
        const topK = s.vectorTopK || 5;
        const threshold = s.vectorThreshold || 0.6;
        let results = await cdSearchVectors(scene, data.diaryVectors, topK, threshold);
        // ★ rerank xếp hạng lại (luồng nhật ký nhân vật)
        results = await cdRerankResults(scene, results, s, 'diary');
        if (results.length) {
          diaryMemory = 'Nhật ký lịch sử liên quan (truy xuất vector):\n' + results.map(r => '  - ' + (r.text || '').trim()).join('\n');
        }
      }
    } catch (e) { cdWarn('Truy xuất vector nhật ký thất bại (hạ cấp thành ký ức toàn bộ):', e); }
  }
  const _dv = (s && s.diaryVersion === 'lite') ? 'lite' : 'full';
  const sys = [
    'Bạn là người ghi chép "Nhật ký nhân vật". Khi đọc cốt truyện, hãy để mỗi nhân vật có tên tuổi và có đất diễn dùng ngôi thứ nhất viết ra điều mình thực sự đang nghĩ trong lòng lúc này.',
    (typeof data === 'object' && data !== null && typeof data.lastFloor === 'number' && data.lastFloor === -1)
      ? '- ★★★ Lần này là lần ghi chép【đầu tiên】của đoạn cốt truyện này. 【Lời mở đầu ở tầng 0】ở phần đầu chứa thiết lập bối cảnh, thời gian địa điểm, các nhân vật xuất hiện và trạng thái quan hệ hiện tại giữa họ; hãy lĩnh hội các thiết lập này, nhưng đừng thuật lại lời mở đầu, chỉ hòa lớp bối cảnh này vào tâm cảnh lúc này của nhân vật.'
      : '',
    '【Viết cho ai】Chỉ viết cho nhân vật có tên tuổi và có đất diễn. Bỏ qua người qua đường thuần túy; không viết thay người chơi/nhân vật chính.',
    s.mainCardIsGM ? '- Người dẫn truyện/hệ thống/góc nhìn thượng đế/người kể chuyện kiểu GM thì đừng viết cho họ.' : '',
    '【Đây là lời tự nhủ viết cho chính mình, không phải báo cáo cốt truyện】',
    '- Viết theo cảm xúc và tính khí lúc này của nhân vật, đừng như học thuộc bài mà thuật lại hôm nay đã xảy ra chuyện gì. Chỉ viết những gì họ tận mắt thấy, tận tai nghe, tự thân trải nghiệm, và trong lòng thật sự nghĩ như vậy.',
    '- Lệnh cấm toàn tri: tuyệt đối không được như thượng đế mà nói ra nhân vật khác đang nghĩ gì trong lòng, không được viết tình tiết nhân vật này không biết, chưa trải qua.',
    '【Phần trọng tâm】Viết ra chuyện trong đoạn cốt truyện này thật sự chạm vào lòng họ —— họ có thể vì chuyện này mà thay đổi cách nhìn về ai đó, ghi thù, rung động, sợ hãi về sau, biết ơn, tức đến bật cười, hoặc tự cà khịa bản thân một trận ra trò; cũng có thể chỉ là trong lòng chợt thót một cái, cái mùi vị mà chính họ cũng không nói rõ được. Đi theo phản ứng mà nhân vật đó nên có: vui thì vui, chua thì chua, nhận thì nhận, giận thì giận. Điểm mấu chốt là chuyện này mang theo cảm xúc rơi vào lòng họ, khiến họ có chút cách nhìn hoặc thái độ mới về một người nào đó hoặc về chính mình.',
    '【Giọng điệu】Như một mình lẩm bẩm lúc đêm khuya: có thể có ẩn ý, nói nửa chừng rồi nuốt lại, đột nhiên tự giễu một câu, hoặc cứng miệng hai câu; sẽ lặp đi lặp lại, sẽ mâu thuẫn —— con người vốn là như vậy. Đừng văn vẻ, đừng giọng quan cách, đừng câu nào cũng giải thích vì sao.',
    '【Ký ức】Nhớ lại chuyện cũ thì thêm một câu hô ứng, không nhớ thì thôi, không gượng ép.',
    '【Ngôn ngữ】Theo ngôn ngữ chính của đoạn cốt truyện.',
    '【Tình tiết lộ liễu】Tình dục/bạo lực... chỉ lướt qua bằng một câu (như "đã quan hệ với anh ấy", "bị hắn khống chế"), nghiêm cấm miêu tả chi tiết động tác, cơ quan, dịch thể. Nhật ký ghi cảm nhận và phán đoán, không phải tái hiện quá trình.',
    (_dv === 'lite'
      ? '【Lô này là bản ngắn】Chính văn trong vòng 100 chữ, chỉ viết ba thứ thật cô đọng: ① lúc này trong lòng nghĩ gì (sướng hay không/ấm ức hay không/buông bỏ được chưa) ② chuyện quan trọng nhất hôm nay (một câu lướt qua, mang theo thái độ của họ —— cà khịa/biết ơn/ghi thù/rung động đều được) ③ một điểm ký ức họ muốn giữ lại từ chuyện này. Câu nào ra câu nấy, không chất chồng từ ngữ, không dài dòng.'
      : '【Lô này là bản đầy đủ】Chính văn 300~520 chữ. Trải ra theo cảm xúc: có thể có hoạt động tâm lý, có giọng điệu, viết chuyện chạm vào lòng họ sao cho có sức nặng. Thà thiếu chứ không ẩu, đừng viết rỗng cho đủ chữ.'),
    '【Cấu trúc】Chỉ xuất JSON, các trường giữ nguyên, không được cắt bớt:',
    '{"npcs":[{"name":"Tên chính","aliases":["Bí danh"],"is_minor":false,"date":"Thời gian trong truyện hoặc tầng N","turn":số_tầng,"entry":"Chính văn lời tự nhủ ngôi thứ nhất", "mood":"Tâm trạng (chỉ dùng một trong các từ sau: vui vẻ, buồn bã, tức giận, căng thẳng, bình tĩnh, bối rối, ngạc nhiên, nhớ nhung)","attitude_to_user":"Thái độ với người dùng","secret":"Tâm tư chưa nói ra (có thể trùng với entry nhưng riêng tư hơn, ngắn hơn)","key_events":["Sự kiện then chốt"],"relationship_with_others":{"Nhân vật nào đó":"Mô tả quan hệ"}}]}',
    'Giải thích các trường:',
    '- entry: chính là chính văn lời tự nhủ của nhân vật lúc này (viết theo số chữ của bản ngắn/bản đầy đủ ở trên).',
    '- mood: tâm trạng lúc này; attitude_to_user: thái độ với người dùng; secret: tâm tư chưa nói ra.',
    '- key_events: sự kiện họ tự thân trải qua và có sức nặng với cá nhân họ.',
    '- relationship_with_others: ấn tượng của họ về quan hệ giữa mình và người khác (chủ quan, viết theo trải nghiệm của họ, không phải kết luận từ góc nhìn thượng đế).',
    '- Dùng lại tên chính trong danh sách nhân vật đã biết; nhận ra bí danh thì gộp về tên chính và bổ sung vào aliases.',
    '- Dùng is_minor để đánh dấu tầm quan trọng của nhân vật: nhân vật chính/nhân vật phụ quan trọng/NPC có tên tuổi và có đất diễn đánh false; người qua đường thuần túy chỉ lộ mặt một hai câu trong đoạn đánh true.',
  ].filter(Boolean).join('\n');
  // ★ Liên kết sách thế giới: ở đầu thân hàm, lấy bất đồng bộ thiết lập sách thế giới của nhân vật xuất hiện (loadWorldInfo là API bất đồng bộ)
  let _worldbookTxtDiary = '';
  if (s && s.summarizeInjectDiary && s.worldbookLink !== false) {
    try {
      const _wr = cdSceneWorldbookRoles(windowFloors, data);
      if (_wr.length) _worldbookTxtDiary = await cdGetWorldbookForRoles(_wr);
    } catch (e) { if (typeof cdWarn === 'function') cdWarn('Đọc liên kết sách thế giới (nhật ký) thất bại:', e); }
  }
  const usr = [
    known.length ? `Danh sách nhân vật đã biết:${known.join('; ')}` : 'Danh sách nhân vật đã biết: (chưa có)',
    diaryMemory ? `Ký ức hiện có của từng nhân vật (lịch sử gần nhất):\n${diaryMemory}` : 'Ký ức hiện có của từng nhân vật: (chưa có)',
    `Đoạn cốt truyện lần này:\n${scene}`,
    // ★ Nhân vật trọng điểm: nhân vật do người dùng chỉ định thủ công phải được viết chi tiết, tránh bị bỏ sót/lệch thiết lập
    (Array.isArray(data.focusRoles) && data.focusRoles.length)
      ? `【Nhân vật trọng điểm (bắt buộc viết nhật ký chi tiết)】\n${data.focusRoles.map(f => '  - ' + (f.name || '') + (f.note ? `:${f.note}` : '')).join('\n')}\nYêu cầu: dù những nhân vật này xuất hiện ít trong đoạn lần này, vẫn phải dựa vào ký ức và thiết lập sẵn có để viết bù nhật ký đầy đủ, đúng nhân thiết cho họ.`
      : '',
    // ★ Liên kết sách thế giới: chèn thiết lập sách thế giới của các nhân vật xuất hiện lần này (viết sát nhân thiết hơn)
    _worldbookTxtDiary ? '【Tham khảo thiết lập sách thế giới (nhân vật xuất hiện lần này)】\n' + _worldbookTxtDiary : '',
    'Hãy xuất JSON.',
  ].filter(Boolean).join('\n\n');
  return [
    { role: 'system', content: JAILBREAK + '\n\n' + sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: '{"npcs":[' },
  ];
}

/** ★ Prompt gộp: một lần gọi hoàn thành nhật ký + quan hệ + hồ sơ cốt truyện */
function cdBuildCombinedPrompt(windowFloors, data, s) {
  const known = Object.keys(data.diaries).map(name => {
    const al = (data.aliases[name] || []);
    return al.length ? `${name}(bí danh:${al.join(', ')})` : name;
  });
  // ★ Mỗi nhân vật chèn nhiều mục lịch sử gần nhất (mặc định vectorTopK mục), tránh chỉ chèn mục mới nhất của mỗi nhân vật
  const memLimit = Math.max(1, parseInt(s.vectorTopK, 10) || 5);
  const memory = Object.entries(data.diaries).map(([name, list]) => {
    if (!Array.isArray(list) || !list.length) return '';
    return list.slice(-memLimit).map(function (e) {
      return `【${name}】${e.date ? e.date : 'Tầng ' + e.turn + ''}: ${(e.entry || '').trim()}`;
    }).join('\n');
  }).filter(Boolean).join('\n');
  const scene = windowFloors.map(m => `[#${m.message_id} ${m.name}] ${m.mes}`).join('\n\n');
  const existing = data.archive || emptyData().archive;
  
  const sys = [
    'Bạn là trợ lý AI ba trong một: "người ghi chép nhật ký nhân vật" + "người phân tích quan hệ nhân vật" + "người chỉnh lý hồ sơ cốt truyện".',
    'Đọc đoạn cốt truyện được cung cấp, đồng thời hoàn thành ba nhiệm vụ sau.',
    '',
    '=== Nhiệm vụ một: Nhật ký nhân vật ===',
    'Cho mỗi nhân vật xuất hiện có tên tuổi và có đất diễn, viết bằng góc nhìn chủ quan ngôi thứ nhất của chính nhân vật đó một bài **nhật ký nội tâm riêng tư tràn đầy cảm giác người thật**.',
    'Yêu cầu:',
    '- Chỉ viết cho nhân vật có tên, có đất diễn thực sự. Bỏ qua người qua đường thuần túy, quần chúng vô danh.',
    '- Đừng viết nhật ký cho nhân vật người dùng/người chơi.',
    s.mainCardIsGM ? '- Nếu nhân vật nào là người dẫn truyện/hệ thống/góc nhìn thượng đế/người kể chuyện kiểu GM, đừng viết cho họ.' : '',
    '- Ngôi thứ nhất, mang cảm xúc, tư tâm, cách hiểu chủ quan của nhân vật đó (có thể lệch so với sự thật).',
    '- ★★★ entry là "nhật ký riêng tư viết cho chính mình đọc", không phải thuật lại cốt truyện, không phải báo cáo. Phải như người thật đêm khuya tiện tay ghi lại hiện trạng nội tâm, chứ không phải bản tổng kết đều đều.',
    '- ★★★ Nội tâm thẳng thắn + ngây ngô tương phản (hơi thở người thật): cho phép nhân vật chuyển đổi tự nhiên giữa "bình tĩnh toan tính/từng trải" và "dỗi hờn/trẻ con/tính khí nhỏ nhặt"; đừng tô vẽ văn chương, đừng câu nào cũng giải thích "vì sao".',
    '- ★★★ Cung cấp "kho chất liệu nội tâm", tầng nào có chuyện thì viết tầng đó, không cần gượng ép: ① sự kiện bề mặt (khung xương) ② điều tôi để tâm (động cơ ngầm) ③ sổ nợ với người ấy (nợ cũ/khoảng chênh) ④ kế hoạch chưa nói với ai (mưu tính) ⑤ điều chính mình cũng không thừa nhận (tự lừa dối, dẫn ra bằng "tôi đâu có/thôi kệ/thật ra").',
    '- ★★★ Vòng lặp ký ức: người/việc/cảm xúc lần trước đã nhắc trong ký ức hiện có thì cố gắng hô ứng ở lần này, tạo thành bộ phim nội tâm liên tục xuyên các bài.',
    '- ★★★ Cho phép để trống và nửa câu ("……"/viết nửa chừng thì dừng), còn có nội tâm hơn là viết kín.',
    '- Khi liên quan tình tiết lộ liễu chỉ cần khái quát ngắn gọn, nghiêm cấm miêu tả từng chữ.',
    '- Dùng lại tên chính trong "danh sách nhân vật đã biết"; nếu nhận ra bí danh/cách gọi khác, gộp về tên chính đã có, và bổ sung bí danh vào aliases.',
    '- Ngôn ngữ: theo ngôn ngữ chính của đoạn cốt truyện.',
    '- Dùng is_minor để đánh dấu tầm quan trọng của nhân vật.',
    '',
    '=== Nhiệm vụ hai: Quan hệ nhân vật ===',
    'Trích xuất "quan hệ chủ quan một chiều" giữa các nhân vật.',
    'Yêu cầu:',
    '- Chủ quan một chiều: quan hệ from nhìn to. A nhìn B và B nhìn A có thể khác nhau, hãy ghi riêng mỗi chiều một mục.',
    '- Chỉ phân tích quan hệ giữa các nhân vật có tên tuổi và có đất diễn, bỏ qua người qua đường thuần túy.',
    '- Không bao gồm nhân vật người dùng/người chơi.',
    '- type: dùng từ ngắn gọn khái quát tính chất quan hệ (như "bạn chí cốt", "thầm thương", "thù địch", "chủ tớ", "cảnh giác", "phụ thuộc").',
    '- attitude: chỉ được là một trong "positive" (thân thiện), "negative" (bài xích), "neutral" (trung lập).',
    '- note: một câu giải thích (trong vòng 20 chữ).',
    known.length ? `Nhân vật đã biết:${known.join(', ')}` : '',
    '',
    '=== Nhiệm vụ ba: Hồ sơ cốt truyện ===',
    'Chỉnh lý cốt truyện thành hồ sơ cốt truyện có thể viết tiếp lâu dài.',
    'Yêu cầu:',
    '- Mỗi mô tả sự kiện phải bắt đầu bằng【mốc thời gian】, như【15/03/2026 18:30】, 【Tầng 15】.',
    '- Chỉ viết sự thật đã xảy ra, không viết suy đoán, đánh giá, tô vẽ không khí hay phân tích tâm lý.',
    '- Chuyện phiếm không có tác dụng thúc đẩy cốt truyện có thể nén lại.',
    '- Trong sự kiện xuất hiện vật phẩm, chứng cứ, số tiền, thuốc men, thương bệnh, thay đổi quan hệ... thì phải viết rõ nội dung cụ thể.',
    '',
    existing.mainline ? `Tuyến chính hiện có:${existing.mainline}` : '',
    existing.sideline ? `Tuyến phụ hiện có:${existing.sideline}` : '',
    existing.states ? `Trạng thái quan trọng hiện có:${existing.states}` : '',
    existing.unresolved ? `Việc chưa giải quyết hiện có:${existing.unresolved}` : '',
    '',
    'Định dạng đầu ra: xuất ba phần nội dung nghiêm ngặt theo thứ tự sau, phân cách bằng "===SEPARATOR===".',
    '',
    'Phần một: JSON nhật ký',
    '{"npcs":[{"name":"Tên chính","aliases":["Bí danh"],"is_minor":false,"date":"Thời gian trong truyện hoặc tầng N","turn":số_tầng,"entry":"Chính văn ngôi thứ nhất","mood":"Tâm trạng (chỉ dùng một trong các từ sau: vui vẻ, buồn bã, tức giận, căng thẳng, bình tĩnh, bối rối, ngạc nhiên, nhớ nhung)","attitude_to_user":"Thái độ với người dùng","secret":"Tâm tư chưa nói ra","key_events":["Sự kiện then chốt"],"relationship_with_others":{"Nhân vật nào đó":"Mô tả quan hệ"}}]}',
    '',
    '===SEPARATOR===',
    '',
    'Phần hai: JSON quan hệ',
    '{"relations":[{"from":"A","to":"B","type":"tính chất quan hệ","attitude":"positive","note":"giải thích ngắn"}]}',
    'Nếu không có quan hệ nào, xuất {"relations":[]}',
    '',
    '===SEPARATOR===',
    '',
    'Phần ba: Hồ sơ cốt truyện',
    'Tuyến chính:',
    'Tuyến phụ:',
    'Thay đổi trạng thái quan trọng:',
    'Việc chưa giải quyết:',
    'Nếu không có thay đổi, trường tương ứng xuất "Không".',
    '',
    '===SEPARATOR===',
  ].filter(Boolean).join('\n');
  
  const usr = [
    known.length ? `Danh sách nhân vật đã biết:${known.join('; ')}` : 'Danh sách nhân vật đã biết: (chưa có)',
    memory ? `Ký ức hiện có của từng nhân vật (lịch sử gần nhất):\n${memory}` : 'Ký ức hiện có của từng nhân vật: (chưa có)',
    `Đoạn cốt truyện lần này:\n${scene}`,
  ].join('\n\n');
  
  return [
    { role: 'system', content: JAILBREAK + '\n\n' + sys },
    { role: 'user', content: usr },
    { role: 'assistant', content: '{"npcs":[' },
  ];
}

