/* ================== Trang danh sách nhóm (trang chủ Tiểu kịch trường) ================== */
/* Lớp phủ Tiểu kịch trường: mô phỏng cdForumOpen của diễn đàn, phủ kín toàn bộ panel plugin #cd-modal-root */
function cdTheatreOpen() {
  cdTgInjectStyle();
  var panel = document.getElementById('cd-modal-root');
  if (!panel) { cdWarn('[Tiểu kịch trường] Panel plugin chưa sẵn sàng'); return; }
  if (panel.style.display === 'none') panel.style.display = '';
  // ★ Chẩn đoán: ghi lại các lớp anh em mà panel hiện đang gắn (có thể còn sót lớp phủ trong suốt che mất thao tác bấm)
  try {
    var _shadows = [];
    var _pp = panel.parentElement;
    if (_pp) [].forEach.call(_pp.children, function (ch) { if (ch && ch !== panel) _shadows.push(ch.id || ch.className || ch.tagName); });
    console.log('[Tiểu kịch trường·Chẩn đoán] Các node anh em của #cd-modal-root (có thể là lớp phủ ở trên/dưới panel):', _shadows.join(',') || '(không có)');
  } catch (_e) {}

  // ★ Phòng vệ: xóa lớp phủ toàn màn hình có thể còn sót (chép theo cdForumOpen của diễn đàn, tránh che mất thao tác bấm/nút)
  try { [].forEach.call(document.querySelectorAll('.cd-overlay,.cd-modal-overlay-dedupe,.cd-modal-overlay,#cd-dedupe-test-overlay'), function (_ov2) { if (_ov2 && _ov2.parentNode) { _ov2.parentNode.removeChild(_ov2); } }); } catch (_e1) {}
  try { var _em2 = document.getElementById('cfEditorMask'); if (_em2) { _em2.classList.remove('open'); _em2.style.display = 'none'; } } catch (_e2) {}
  try { var _iv2 = document.getElementById('cfImgViewMask'); if (_iv2) _iv2.style.display = 'none'; } catch (_e3) {}

  var ov = document.getElementById('cd-theatre-overlay');
  if (!ov) {
    ov = document.createElement('div'); ov.id = 'cd-theatre-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:2000010;display:none;flex-direction:column;background:#fafbfc;overflow:hidden;';
    panel.appendChild(ov);
  }
  ov.innerHTML = '<div style="pointer-events:auto;width:100%;height:100%;display:flex;flex-direction:column;overflow:hidden;background:#fafbfc;">' +
    '<div class="cd-tg-ovbar"><span class="cd-tg-ovback" onclick="cdTheatreClose()" title="Quay lại">' + cdTgIco('back') + '</span><span class="cd-tg-ovttl">Tiểu kịch trường</span></div>' +
    '<div class="cd-tg-ovcnt" id="cd-theatre-content"></div>' +
    '</div>';
  ov.style.display = 'flex';
  cdTgRenderGroups();

  // ★ Chẩn đoán: sau khi mở, dò xem vị trí bấm ở tâm lớp phủ thực tế trúng mục tiêu nào (xem có lớp phủ trong suốt chắn trên thẻ không)
  try {
    setTimeout(function () {
      var _c = document.getElementById('cd-theatre-content');
      var _probe;
      if (_c) {
        var _r = _c.getBoundingClientRect();
        var _cx = _r.left + Math.min(40, _r.width / 2);
        var _cy = _r.top + Math.min(40, _r.height / 2);
        _probe = document.elementFromPoint(_cx, _cy);
      }
      console.log('[Tiểu kịch trường·Chẩn đoán] elementFromPoint trúng:', _probe ? (_probe.id || _probe.className || _probe.tagName) : '(null)', '| Điểm trúng có nằm trong lớp phủ Tiểu kịch trường không:', _probe ? !!_probe.closest('#cd-theatre-overlay') : false, '| onclick của tổ tiên bấm được mà điểm trúng thuộc về:', _probe ? (_probe.closest('[onclick]') ? (_probe.closest('[onclick]').getAttribute('onclick') || '(inline)') : '(không có onClick)') : '(không có)');
    }, 80);
  } catch (_e4) {}
}
function cdTheatreClose() {
  var ov = document.getElementById('cd-theatre-overlay');
  if (ov) { ov.style.display = 'none'; ov.innerHTML = ''; }
}
/* Điểm gắn nội dung Tiểu kịch trường hiện tại: lớp phủ đang mở thì render vào container nội dung của lớp phủ, nếu không thì render vào #cd-content */
function cdTgMountEl() {
  var c = document.getElementById('cd-theatre-content');
  return c || document.getElementById('cd-content');
}
/* ===== Cửa sổ tự vẽ trong trang (Android WebView cấm prompt/confirm, nên đi hết qua đây) ===== */
function cdTgDlg() {
  var d = document.getElementById('cd-tg-dlg');
  if (!d) { d = document.createElement('div'); d.id = 'cd-tg-dlg'; d.addEventListener('click', function(){ d.classList.remove('on'); }); document.body.appendChild(d); }
  d.setAttribute('class', 'cd-tg-modal cd-tg-adv');
  return d;
}
/* Cửa sổ một ô nhập chung: label = tiêu đề gợi ý, ph = placeholder, init = giá trị ban đầu, cb(value|null) */
function cdTgPrompt(label, ph, init, cb) {
  var d = cdTgDlg();
  var safeInit = cdTgEscapeHtml(init || '');
  d.innerHTML = '<div class="cd-tg-box" onclick="event.stopPropagation()">' +
    '<div style="font-size:13.5px;font-weight:700;margin-bottom:12px;">' + cdTgEscapeHtml(label) + '</div>' +
    '<input id="cd-tg-prompt-v" type="text" value="' + safeInit + '" placeholder="' + cdTgEscapeHtml(ph || '') + '" style="margin-bottom:10px;">' +
    '<div style="display:flex;gap:8px;margin-top:4px;">' +
    '<div class="cd-tg-mbtn" onclick="cdTgPromptCancel()">Hủy</div>' +
    '<div class="cd-tg-mbtn primary" onclick="cdTgPromptOk()">Đồng ý</div>' +
    '</div></div>';
  d.classList.add('on');
  window._cdTgPromptCb = cb;
  var inp = document.getElementById('cd-tg-prompt-v');
  setTimeout(function(){ if (inp) { inp.focus(); } }, 10);
}
function cdTgPromptOk() {
  var v = document.getElementById('cd-tg-prompt-v') ? document.getElementById('cd-tg-prompt-v').value : '';
  cdTgDlg().classList.remove('on');
  var cb = window._cdTgPromptCb; window._cdTgPromptCb = null;
  if (cb) cb(v);
}
function cdTgPromptCancel() {
  cdTgDlg().classList.remove('on');
  var cb = window._cdTgPromptCb; window._cdTgPromptCb = null;
  if (cb) cb(null);
}
/* Cửa sổ xác nhận chung: msg = nội dung, okLabel/okLabel (mặc định Đồng ý/Hủy) */
function cdTgConfirm(msg, cb, okLabel) {
  var d = cdTgDlg();
  d.innerHTML = '<div class="cd-tg-box" onclick="event.stopPropagation()">' +
    '<div style="font-size:12.5px;font-weight:600;margin-bottom:12px;line-height:1.6;">' + cdTgEscapeHtml(msg || '') + '</div>' +
    '<div style="display:flex;gap:8px;margin-top:4px;">' +
    '<div class="cd-tg-mbtn" onclick="cdTgConfirmResp(false)">Hủy</div>' +
    '<div class="cd-tg-mbtn primary" onclick="cdTgConfirmResp(true)">' + cdTgEscapeHtml(okLabel || 'Đồng ý') + '</div>' +
    '</div></div>';
  d.classList.add('on');
  window._cdTgConfirmCb = cb;
}
function cdTgConfirmResp(yes) {
  cdTgDlg().classList.remove('on');
  var cb = window._cdTgConfirmCb; window._cdTgConfirmCb = null;
  if (cb) cb(!!yes);
}
function cdRenderTheatre() {
  cdTgInjectStyle();
  _cdTgOpenGroup = null;
  cdTheatreOpen();
}
function cdTgRenderGroups() {
  const groups = cdTgGetGroups();
  const gIco = { 'Thường dùng': 'book', 'Chiến đấu': 'sword', 'Thường ngày': 'smile', 'Yêu thích': 'star' };
  let html = ['<div class="cd-tg-wrap">'];
  html.push('<div class="cd-tg-hd"><span class="cd-tg-title">Tiểu kịch trường</span><span class="cd-tg-gear" onclick="cdTgRenderSettings()" title="Thiết lập tên thay thế">' + cdTgIco('gear') + '</span></div>');
  groups.forEach(function (g) {
    const cnt = Array.isArray(g.items) ? g.items.length : 0;
    const ico = gIco[g.name] || 'book';
    const cls = (g.name === 'Yêu thích') ? ' cd-tg-fav' : '';
    const safe = String(g.name).replace(/'/g, "\\'").replace(/"/g, '"');
    html.push('<div class="cd-tg-card' + cls + '" onclick="cdTgOpenGroup(\'' + safe + '\')"><div class="cd-tg-ic">' + cdTgIco(ico) + '</div><div class="cd-tg-info"><div class="cd-tg-name">' + cdTgEscapeHtml(g.name) + '</div><div class="cd-tg-meta">' + cnt + ' tiểu kịch</div></div><div class="cd-tg-arrow">' + cdTgIco('arrow') + '</div></div>');
  });
  if (!groups.some(function (g) { return g.name === 'Yêu thích'; })) {
    html.push('<div class="cd-tg-card cd-tg-fav"><div class="cd-tg-ic">' + cdTgIco('star') + '</div><div class="cd-tg-info"><div class="cd-tg-name">Yêu thích</div><div class="cd-tg-meta">Các tiểu kịch đã yêu thích sẽ xuất hiện ở đây</div></div></div>');
  }
  html.push('<div class="cd-tg-card cd-tg-add" onclick="cdTgNewGroup()"><div class="cd-tg-ic">' + cdTgIco('plus') + '</div><div class="cd-tg-info"><div class="cd-tg-name">Tạo nhóm mới</div><div class="cd-tg-meta">Lập một nhóm của riêng bạn</div></div></div>');
  html.push('</div>');
  try {
    var _mt = cdTgMountEl();
    _mt.innerHTML = html.join('');
    cdApplyFontScale();
  } catch (er) {
    try { console.log('[Tiểu kịch trường·Lỗi render]', er && er.stack ? er.stack : er); } catch (_e) {}
    var _mc = document.getElementById('cd-theatre-content');
    if (_mc) { _mc.innerHTML = '<div style="padding:18px;color:#c0392b;font-size:12px;white-space:pre-wrap;">Render nhóm Tiểu kịch trường bị lỗi (đã chặn và hiển thị):\n' + cdTgEscapeHtml(er && er.message ? er.message : er) + '</div>'; }
  }
}
function cdTgOpenGroup(name) {
  console.log('[Tiểu kịch trường·Chẩn đoán] cdTgOpenGroup được kích hoạt, nhóm đích=', name);
  _cdTgOpenGroup = name;
  cdTgRenderItems();
}
function cdTgEscapeHtml(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '"'); }
async function cdTgRenderItems() {
  cdTgInjectStyle();
  const name = _cdTgOpenGroup;
  const groups = cdTgGetGroups();
  const isFavView = (name === 'Yêu thích');
  const g = groups.find(function (x) { return x.name === name; });
  // ★ View yêu thích: thu thập xuyên nhóm mọi mục fav=true (kèm định vị nguồn)
  let items = [];
  if (isFavView) {
    groups.forEach(function (gg) {
      if (gg.name === 'Yêu thích') return;
      (Array.isArray(gg.items) ? gg.items : []).forEach(function (it, i) {
        if (it.fav === true) items.push({ title: it.title, content: it.content, fav: true, _srcGroup: gg.name, _srcIdx: i });
      });
    });
  } else {
    items = ((g && Array.isArray(g.items)) ? g.items : []).map(function (it, i) { return { title: it.title, content: it.content, fav: (it.fav === true), _srcGroup: name, _srcIdx: i }; });
  }
  let html = ['<div class="cd-tg-wrap">'];
  html.push('<div class="cd-tg-hd"><span class="cd-tg-back" onclick="cdTgRenderGroups()">' + cdTgIco('back') + '</span><span class="cd-tg-title">' + cdTgEscapeHtml(name) + '</span><span class="cd-tg-gear" onclick="cdTgRenderSettings()" title="Thiết lập tên thay thế">' + cdTgIco('gear') + '</span></div>');
  if (!items.length) html.push('<div class="cd-tg-no">' + (isFavView ? 'Chưa có tiểu kịch yêu thích nào<br>Bấm sáng ngôi sao trên mục là nó sẽ xuất hiện ở đây' : 'Nhóm này chưa có tiểu kịch nào<br>Bấm dấu + bên dưới để thêm một mục') + '</div>');
  items.forEach(function (it, idx) {
    const srcGroupRaw = String(it._srcGroup || name).replace(/'/g, "\\'");
    html.push('<div class="cd-tg-item">');
    html.push('<div class="cd-tg-irow"><span class="cd-tg-it">' + cdTgEscapeHtml(it.title) + '</span><span class="cd-tg-favt' + (it.fav ? ' on' : '') + '" onclick="cdTgToggleFav(\'' + srcGroupRaw + '\',' + it._srcIdx + ')" title="Yêu thích">' + cdTgIco('star') + '</span></div>');
    html.push('<div class="cd-tg-prev">' + cdTgEscapeHtml(it.content) + '</div>');
    html.push('<div class="cd-tg-brow"><div class="cd-tg-btn cd-tg-send" onclick="cdTgSendChat(' + idx + ')">' + cdTgIco('send') + 'Gửi</div><div class="cd-tg-btn" onclick="cdTgFillBox(' + idx + ')">' + cdTgIco('fill') + 'Điền ô</div><div class="cd-tg-btn cd-tg-edit" onclick="cdTgEditItem(' + idx + ')">' + cdTgIco('edit') + 'Sửa</div></div>');
    html.push('</div>');
  });
  if (!isFavView) {
    html.push('<div class="cd-tg-top"><div class="cd-tg-plus" onclick="cdTgNewItem()">' + cdTgIco('plus') + '</div><div class="cd-tg-tip">Thêm tiểu kịch mới vào nhóm hiện tại</div></div>');
  }
  html.push('</div>');
  cdTgMountEl().innerHTML = html.join('');
  /* Ghi lại đường dẫn nguồn đang render, để gửi/điền ô/sửa định vị chính xác */
  window._cdTgRenderItems = items.map(function (it) { return { srcGroup: it._srcGroup, srcIdx: it._srcIdx }; });
}
function cdTgNewGroup() {
  cdTgPrompt('Tên nhóm mới:', 'Ví dụ: Thường ngày, Chiến đấu…', '', function (v) {
    if (!v || !String(v).trim()) return;
    const groups = cdTgGetGroups();
    if (groups.some(function (g) { return g.name === String(v).trim(); })) { if (typeof toastr !== 'undefined') toastr.warning('Đã có nhóm trùng tên'); return; }
    groups.push({ name: String(v).trim(), items: [] });
    cdTgSaveGroups(groups);
    cdTgRenderGroups();
  });
}
function cdTgNewItem() { cdTgEditItem(-1); }
function cdTgEditItem(idx) {
  let src;
  if (idx === -1) { src = { title: '', content: '' }; }
  else { const loc = cdTgLocate(idx); src = loc ? loc.it : { title: '', content: '' }; }
  let dlg = document.getElementById('cd-tg-dlg');
  if (!dlg) { dlg = document.createElement('div'); dlg.id = 'cd-tg-dlg'; dlg.addEventListener('click', function(){ dlg.classList.remove('on'); }); document.body.appendChild(dlg); }
  dlg.setAttribute('class', 'cd-tg-modal');
  dlg.innerHTML = '<div class="cd-tg-box" onclick="event.stopPropagation()"><div style="font-size:13.5px;font-weight:700;margin-bottom:12px;">' + (idx === -1 ? 'Tạo tiểu kịch mới' : 'Sửa tiểu kịch') + '</div><div style="font-size:11px;color:#5b5f66;margin-bottom:4px;">Tiêu đề</div><input id="cd-tg-dlg-t" type="text" value="' + cdTgEscapeHtml(src.title) + '" placeholder="Tiêu đề một câu"><div style="font-size:11px;color:#5b5f66;margin-bottom:4px;">Nội dung (có thể dùng {{user}} / {{chat}})</div><textarea id="cd-tg-dlg-c" placeholder="Nhập nội dung tiểu kịch…">' + cdTgEscapeHtml(src.content) + '</textarea><div style="display:flex;gap:8px;margin-top:4px;"><div class="cd-tg-mbtn" onclick="document.getElementById(\'cd-tg-dlg\').classList.remove(\'on\')">Hủy</div><div class="cd-tg-mbtn primary" onclick="cdTgSaveItem(' + idx + ')">Lưu</div></div></div>';
  dlg.classList.add('on');
}
function cdTgSaveItem(idx) {
  const t = document.getElementById('cd-tg-dlg-t') ? document.getElementById('cd-tg-dlg-t').value : '';
  const c = document.getElementById('cd-tg-dlg-c') ? document.getElementById('cd-tg-dlg-c').value : '';
  const groups = cdTgGetGroups();
  if (idx === -1) {
    // Tạo mới: ghi vào nhóm thật đang mở; nếu hiện là view yêu thích thì rơi vào nhóm không phải yêu thích đầu tiên
    let g;
    if (_cdTgOpenGroup !== 'Yêu thích') { g = groups.find(function (x) { return x.name === _cdTgOpenGroup; }); }
    if (!g) { g = groups.find(function (x) { return x.name !== 'Yêu thích'; }) || groups[0]; }
    if (!g) { if (typeof toastr !== 'undefined') toastr.warning('Hãy tạo một nhóm trước'); const dlg = document.getElementById('cd-tg-dlg'); if (dlg) dlg.classList.remove('on'); return; }
    if (!Array.isArray(g.items)) g.items = [];
    g.items.push({ title: String(t).trim() || 'Chưa đặt tên', content: String(c), fav: false });
  } else {
    const loc = cdTgLocate(idx);
    if (!loc || !loc.it) return;
    loc.it.title = String(t).trim() || 'Chưa đặt tên';
    loc.it.content = String(c);
  }
  cdTgSaveGroups(groups);
  const dlg = document.getElementById('cd-tg-dlg'); if (dlg) dlg.classList.remove('on');
  cdTgRenderItems();
}
function cdTgToggleFav(srcGroup, srcIdx) {
  console.log('[Tiểu kịch trường·Chẩn đoán] cdTgToggleFav được kích hoạt, srcGroup=', srcGroup, 'srcIdx=', srcIdx);
  const groups = cdTgGetGroups();
  // Tương thích cách gọi cũ theo idx (view yêu thích/view thường đều thống nhất đi qua srcGroup+srcIdx)
  let g, realIdx;
  if (typeof srcGroup === 'number') {
    g = groups.find(function (x) { return x.name === _cdTgOpenGroup; });
    realIdx = srcGroup;
  } else {
    g = groups.find(function (x) { return x.name === srcGroup; });
    realIdx = srcIdx;
  }
  if (!g || !g.items || !g.items[realIdx]) return;
  g.items[realIdx].fav = !g.items[realIdx].fav;
  cdTgSaveGroups(groups);
  cdTgRenderItems();
}
/* Định vị mục trong kho lưu trữ thật thông qua số thứ tự render */
function cdTgLocate(idx) {
  const src = (window._cdTgRenderItems && window._cdTgRenderItems[idx]) || null;
  if (!src) return null;
  const groups = cdTgGetGroups();
  const g = groups.find(function (x) { return x.name === src.srcGroup; });
  if (!g || !g.items || !g.items[src.srcIdx]) return null;
  return { group: g, gName: src.srcGroup, it: g.items[src.srcIdx], srcIdx: src.srcIdx };
}
/* ================== Trang thiết lập (tên thay thế: toàn cục + lịch sử chat) ================== */
async function cdTgRenderSettings() {
  console.log('[Tiểu kịch trường·Chẩn đoán] cdTgRenderSettings được kích hoạt (thiết lập bánh răng)');
  cdTgInjectStyle();
  const gm = cdTgGetGlobalMap();
  const cm = await cdTgGetChatMap();
  let html = ['<div class="cd-tg-wrap">'];
  html.push('<div class="cd-tg-hd"><span class="cd-tg-back" onclick="' + (_cdTgOpenGroup ? 'cdTgRenderItems()' : 'cdTgRenderGroups()') + '">' + cdTgIco('back') + '</span><span class="cd-tg-title">Thiết lập tên thay thế</span></div>');
  /* ---- Thay thế toàn cục ---- */
  html.push('<div class="cd-tg-setcard"><div class="cd-tg-scti">' + cdTgIco('globe') + 'Thay thế toàn cục</div><div class="cd-tg-schint">Chọn toàn cục · chuyển sang nhân vật nào vẫn dùng bộ này, không phải điền lại. Không chọn · thẻ nhân vật khác sẽ để trống.</div>');
  html.push('<div class="cd-tg-sel" onclick="cdTgPickGlobal()"><span>' + cdTgSelLabel(gm, 'Toàn cục') + '</span>' + cdTgIco('arrow') + '</div>');
  const gCur = (gm.current && gm.presets && gm.presets[gm.current]) ? gm.presets[gm.current] : { user: '', chat: '' };
  html.push('<div class="cd-tg-map"><span class="cd-tg-mk">{{user}}</span><input data-tg-map="g-user" value="' + cdTgEscapeHtml(gCur.user) + '" placeholder="→ Tên người dùng"></div>');
  html.push('<div class="cd-tg-map"><span class="cd-tg-mk">{{chat}}</span><input data-tg-map="g-chat" value="' + cdTgEscapeHtml(gCur.chat) + '" placeholder="→ Tên nhân vật"></div>');
  html.push('<div class="cd-tg-tags" id="cd-tg-gtags">' + cdTgPresetTags(gm, 'global') + '<span class="cd-tg-tag" onclick="cdTgSaveAsGroup(\'global\')">＋ Lưu thành nhóm</span></div></div>');
  /* ---- Thay thế theo lịch sử chat ---- */
  html.push('<div class="cd-tg-setcard"><div class="cd-tg-scti">' + cdTgIco('chat') + 'Thay thế theo lịch sử chat</div><div class="cd-tg-schint">Chỉ có hiệu lực với cuộc chat hiện tại; mở một lịch sử chat mới thì ở đây trống, phải điền lại.</div>');
  html.push('<div class="cd-tg-sel" onclick="cdTgPickChat()"><span>' + cdTgSelLabel(cm, 'Lịch sử chat') + '</span>' + cdTgIco('arrow') + '</div>');
  const cCur = (cm.current && cm.presets && cm.presets[cm.current]) ? cm.presets[cm.current] : { user: '', chat: '' };
  html.push('<div class="cd-tg-map"><span class="cd-tg-mk">{{user}}</span><input data-tg-map="c-user" value="' + cdTgEscapeHtml(cCur.user) + '" placeholder="→ Tên người dùng"></div>');
  html.push('<div class="cd-tg-map"><span class="cd-tg-mk">{{chat}}</span><input data-tg-map="c-chat" value="' + cdTgEscapeHtml(cCur.chat) + '" placeholder="→ Tên nhân vật"></div>');
  html.push('<div class="cd-tg-tags" id="cd-tg-ctags">' + cdTgPresetTags(cm, 'chat') + '<span class="cd-tg-tag" onclick="cdTgSaveAsGroup(\'chat\')">＋ Lưu thành nhóm</span></div></div>');
  /* ---- Sao lưu dữ liệu (xuất / nhập) ---- */
  const grpCnt = cdTgGetGroups().length;
  html.push('<div class="cd-tg-setcard"><div class="cd-tg-scti">' + cdTgIco('book') + 'Sao lưu dữ liệu</div><div class="cd-tg-schint">Xuất toàn bộ các nhóm Tiểu kịch trường thành bản lưu JSON, đổi thiết bị thì khôi phục một chạm. Hiện có tổng cộng ' + grpCnt + ' nhóm.</div>');
  html.push('<div style="display:flex;gap:8px;margin-top:2px;"><div class="cd-tg-mbtn" onclick="cdTgExport()">Xuất JSON</div><div class="cd-tg-mbtn primary" onclick="cdTgImport()">Nhập JSON</div></div></div>');
  html.push('</div>');
  cdTgMountEl().innerHTML = html.join('');
  /* Ô nhập lưu theo thời gian thực (ủy quyền cho document, lớp phủ / view thường đều kích hoạt được) */
  $(document).on('input', '[data-tg-map]', function () {
    const scope = $(this).attr('data-tg-map').split('-')[0]; // g | c
    cdTgMapInputChanged(scope);
  });
  cdApplyFontScale();
}
function cdTgSelLabel(m, label) {
  if (m && m.current && m.presets && m.presets[m.current]) return 'Nhóm: ' + cdTgEscapeHtml(m.current);
  return '(Tổ hợp chưa lưu)';
}
function cdTgPresetTags(m, scope) {
  if (!m || !m.presets) return '';
  const keys = Object.keys(m.presets);
  if (!keys.length) return '';
  return keys.map(function (k) {
    const on = (m.current === k);
    return '<span class="cd-tg-tag' + (on ? ' cd-tg-cur' : '') + '" onclick="cdTgSwitchPreset(\'' + scope + '\',\'' + String(k).replace(/'/g, "\\'") + '\')">' + cdTgEscapeHtml(k) + '</span>';
  }).join('');
}
function cdTgMapInputChanged(scope) {
  const isG = (scope === 'g');
  const u = ($('[data-tg-map="' + (isG ? 'g' : 'c') + '-user"]').val() || '').trim();
  const c = ($('[data-tg-map="' + (isG ? 'g' : 'c') + '-chat"]').val() || '').trim();
  /* Lưu thành một "nhóm đang sửa hiện tại chưa đặt tên", không chủ động ghi vào presets; chỉ cố định khi lưu thành nhóm */
  if (isG) { cdTgGlobalEphemeral = { user: u, chat: c }; }
  else { cdTgChatEphemeral = { user: u, chat: c }; }
}
function cdTgSaveAsGroup(scope) {
  const isG = (scope === 'global');
  cdTgPrompt('Đặt tên cho nhóm tên thay thế này:', 'Ví dụ: bản đi học / bản chạy đoàn…', '', function (name) {
    if (!name || !String(name).trim()) return;
    const n = String(name).trim();
    const u = ($('[data-tg-map="' + (isG ? 'g' : 'c') + '-user"]').val() || '').trim();
    const c = ($('[data-tg-map="' + (isG ? 'g' : 'c') + '-chat"]').val() || '').trim();
    (async function save() {
      let m = isG ? cdTgGetGlobalMap() : await cdTgGetChatMap();
      if (!m.presets) m.presets = {};
      m.presets[n] = { user: u, chat: c };
      m.current = n;
      if (isG) cdTgSaveGlobalMap(m); else await cdTgSaveChatMap(m);
      cdTgRenderSettings();
    })();
  });
}
async function cdTgSwitchPreset(scope, name) {
  let m = (scope === 'global') ? cdTgGetGlobalMap() : await cdTgGetChatMap();
  m.current = name;
  if (scope === 'global') cdTgSaveGlobalMap(m); else await cdTgSaveChatMap(m);
  cdTgRenderSettings();
}
async function cdTgPickGlobal() {
  const m = cdTgGetGlobalMap(); cdTgPickShared(m, 'global');
}
async function cdTgPickChat() {
  const m = await cdTgGetChatMap(); cdTgPickShared(m, 'chat');
}
async function cdTgPickShared(m, scope) {
  if (!m || !m.presets || !Object.keys(m.presets).length) { if (typeof toastr !== 'undefined') toastr.info(scope === 'global' ? 'Chưa có nhóm thay thế toàn cục, hãy lưu thành nhóm trước' : 'Chưa có nhóm thay thế theo lịch sử chat, hãy lưu thành nhóm trước'); return; }
  const names = Object.keys(m.presets);
  const cur = names.indexOf(m.current);
  const next = names[(cur + 1) % names.length];
  m.current = next;
  if (scope === 'global') cdTgSaveGlobalMap(m); else await cdTgSaveChatMap(m);
  cdTgRenderSettings();
}
/* ================== Sao lưu dữ liệu: xuất / nhập JSON ================== */
function cdTgExport() {
  try {
    const groups = cdTgGetGroups();
    const gm = cdTgGetGlobalMap();
    const payload = { _cd_theatre_v: 1, exportedAt: new Date().toISOString(), groups: groups, globalMap: gm };
    const blobStr = JSON.stringify(payload, null, 2);
    const fname = 'Sao_luu_Tieu_kich_truong_' + new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19) + '.json';
    // Ưu tiên dùng tính năng tải xuống của Tavern/trình duyệt
    let saved = false;
    try {
      const blob = new Blob([blobStr], { type: 'application/json' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = fname;
      document.body.appendChild(a);
      a.click();
      setTimeout(function(){ try { URL.revokeObjectURL(a.href); } catch(e){} document.body.removeChild(a); }, 100);
      saved = true;
    } catch (e) { saved = false; }
    if (!saved) {
      // Hạ cấp: sao chép vào clipboard và hiện cửa sổ tự vẽ để thông báo
      let copied = false;
      if (typeof navigator.clipboard !== 'undefined' && navigator.clipboard.writeText) { try { navigator.clipboard.writeText(blobStr); copied = true; } catch (e) { copied = false; } }
      cdTgConfirm('Trình duyệt không hỗ trợ tải xuống trực tiếp, ' + (copied ? 'đã sao chép toàn bộ JSON vào clipboard, hãy dán và lưu thành file .json.' : 'hãy sao chép JSON dưới đây trong ô nhập bật lên để lưu thủ công:\n\n' + blobStr), function () {}, 'Đã hiểu');
    }
    if (typeof toastr !== 'undefined') toastr.success('Đã xuất (' + groups.length + ' nhóm)');
  } catch (e) {
    if (typeof toastr !== 'undefined') toastr.error('Xuất thất bại: ' + (e && e.message));
  }
}
function cdTgImport() {
  // Đọc một file JSON
  let fileInput = document.getElementById('cd-tg-file');
  if (!fileInput) {
    fileInput = document.createElement('input');
    fileInput.id = 'cd-tg-file';
    fileInput.type = 'file';
    fileInput.accept = '.json,application/json';
    fileInput.style.display = 'none';
    document.body.appendChild(fileInput);
    fileInput.addEventListener('change', function (ev) {
      const f = (ev.target.files && ev.target.files[0]) || null;
      if (!f) return;
      const reader = new FileReader();
      reader.onload = function () {
        cdTgApplyImport(String(reader.result || ''));
      };
      reader.readAsText(f);
      fileInput.value = '';
    });
  }
  fileInput.click();
}
function cdTgApplyImport(text) {
  try {
    const obj = JSON.parse(text);
    const groups = (obj && Array.isArray(obj.groups)) ? obj.groups : null;
    if (!groups) { if (typeof toastr !== 'undefined') toastr.error('Định dạng file nhập không đúng, thiếu groups'); return; }
    // Cho phép ghi đè hoặc thêm vào
    cdTgConfirm('Cách nhập: Đồng ý = ghi đè toàn bộ Tiểu kịch trường hiện tại; Hủy = gộp thêm vào hiện tại', function (mode) {
      if (mode) {
        cdTgSaveGroups(groups);
      } else {
        const cur = cdTgGetGroups();
        groups.forEach(function (g) {
          if (!g || typeof g.name !== 'string') return;
          const exist = cur.find(function (x) { return x.name === g.name; });
          if (exist) { if (Array.isArray(g.items)) (exist.items = exist.items || []).push.apply(exist.items, g.items); }
          else cur.push(g);
        });
        cdTgSaveGroups(cur);
      }
      // Nhóm thay thế toàn cục cũng được khôi phục cùng (chỉ nhập khi ghi đè)
      if (mode && obj && obj.globalMap && obj.globalMap.presets) {
        cdTgSaveGlobalMap({ presets: obj.globalMap.presets || {}, current: obj.globalMap.current || '' });
      }
      if (typeof toastr !== 'undefined') toastr.success('Nhập thành công');
      cdTgRenderSettings();
    }, 'Nhập ghi đè');
  } catch (e) {
    if (typeof toastr !== 'undefined') toastr.error('Nhập thất bại: ' + (e && e.message));
  }
}
/* ================== Gửi vào chat / điền vào ô nhập ================== */
async function cdTgEvalText(idx) {
  const loc = cdTgLocate(idx);
  if (!loc) return '';
  const names = await cdTgCurrentNames();
  return cdTgApplyReplace(loc.it.content, names);
}
async function cdTgSendChat(idx) {
  const text = await cdTgEvalText(idx);
  if (!text) { if (typeof toastr !== 'undefined') toastr.info('Tiểu kịch này trống, không có gì để gửi'); return; }
  try {
    const ctx = SillyTavern.getContext();
    const names = await cdTgCurrentNames();
    const user = (names.userRep && names.userRep.trim()) ? names.userRep : (names.userName || 'user');
    if (ctx && Array.isArray(ctx.chat)) {
      ctx.chat.push({ name: user, is_user: true, is_system: false, is_name: true, send_date: Date.now() / 1000, mes: text, swipes: [], swipe_info: {}, swipes_total: 0, swipe_cur: 0 });
      try { if (typeof ctx.saveChat === 'function') ctx.saveChat(); else if (typeof ctx.saveChatConditional === 'function') ctx.saveChatConditional(); } catch (e) {}
      try { if (typeof ctx.reloadCurrentChat === 'function') ctx.reloadCurrentChat(); } catch (e) {}
      // Kích hoạt để Tavern nhận biết tin nhắn mới
      try { const es = ctx.eventSource || (typeof eventSource !== 'undefined' ? eventSource : null); const et = ctx.event_types || (typeof event_types !== 'undefined' ? event_types : null); if (es && et && et.MESSAGE_SENT) { es.emit(et.MESSAGE_SENT, { mes: text, is_user: true }); } } catch (e) {}
      if (typeof toastr !== 'undefined') toastr.success('Đã gửi vào chat');
    } else if (typeof toastr !== 'undefined') { toastr.error('Không thể truy cập cuộc chat hiện tại'); }
  } catch (e) {
    if (typeof toastr !== 'undefined') toastr.error('Gửi thất bại: ' + (e && e.message));
  }
}
function cdTgFillBox(idx) {
  cdTgEvalText(idx).then(function (text) {
    if (!text) { if (typeof toastr !== 'undefined') toastr.info('Tiểu kịch này trống'); return; }
    try {
      const ta = document.getElementById('send_textarea');
      if (ta) { ta.value = text; ta.dispatchEvent(new Event('input', { bubbles: true })); try { ta.focus(); } catch (e) {} if (typeof toastr !== 'undefined') toastr.success('Đã điền vào ô nhập, bấm gửi để gửi đi'); }
      else {
        const form = document.getElementById('send_form');
        if (form && form.querySelector('textarea')) { const t2 = form.querySelector('textarea'); t2.value = text; t2.dispatchEvent(new Event('input', { bubbles: true })); if (typeof toastr !== 'undefined') toastr.success('Đã điền vào ô nhập'); }
        else if (typeof toastr !== 'undefined') toastr.warning('Không tìm thấy ô nhập của Tavern');
      }
    } catch (e) { if (typeof toastr !== 'undefined') toastr.error('Điền thất bại: ' + (e && e.message)); }
  });
}
/* ================== Vào thẳng từ bong bóng nổi: bấm hai lần vào Tiểu kịch trường ================== */
async function cdTheatreDirect() {
  // Mở panel và chuyển thẳng sang view Tiểu kịch trường
  if (!cdPanelOpen) cdOpenPanel();
  setTimeout(function () { cdSwitchView('theatre'); }, 60);
}

