  var CT_OPTS=[{k:'s',l:'Cốt truyện'},{k:'x',l:'Thế giới khác'},{k:'n',l:'Tin tức'},{k:'lover',l:'Tình cảm'},{k:'gossip',l:'Bát quái'},{k:'fight',l:'Cãi cọ'},{k:'moan',l:'Than vãn'},{k:'angst',l:'Day dứt'},{k:'mo',l:'Nâng niu NVC'},{k:'fan',l:'Đồng nhân'},{k:'ship',l:'Đẩy CP'},{k:'toxic',l:'Tố cáo'},{k:'hate',l:'Chửi mà theo'},{k:'show',l:'Khoe khéo'},{k:'biz',l:'Giao dịch'},{k:'ask',l:'Cầu cứu'},{k:'find',l:'Tìm người'},{k:'joke',l:'Meme nhạt'},{k:'work',l:'Dân làm thuê'},{k:'watch',l:'Hóng chuyện'}];
