    var _title=document.createElement('div');
    _title.style.cssText='font-size:12px;font-weight:800;color:#2f5d50;display:flex;align-items:center;gap:6px;margin-bottom:1px;'; _title.textContent='Đăng bài';
    var _lbl1=document.createElement('div'); _lbl1.style.cssText='font-size:9px;font-weight:700;color:#8b9590;margin-top:1px;'; _lbl1.textContent='Tiêu đề';
    var _ipt1=document.createElement('input'); _ipt1.type='text'; _ipt1.placeholder='Tiêu đề (không bắt buộc)';
    _ipt1.style.cssText='width:100%;border:1px solid #dde5e2;border-radius:9px;background:#fafcfb;color:#2a3a33;font-size:11px;padding:7px 9px;outline:none;box-sizing:border-box;';
    var _lbl2=document.createElement('div'); _lbl2.style.cssText='font-size:9px;font-weight:700;color:#8b9590;margin-top:1px;'; _lbl2.textContent='Nội dung';
    var _ipt2=document.createElement('textarea'); _ipt2.placeholder='Nói gì đó…';
    _ipt2.style.cssText='width:100%;min-height:74px;border:1px solid #dde5e2;border-radius:9px;background:#fafcfb;color:#2a3a33;font-size:11px;padding:7px 9px;outline:none;box-sizing:border-box;resize:vertical;line-height:1.6;';
