        html+='<div style="background:#fff;border:1px solid #e0e8e4;border-radius:9px;overflow:hidden;margin-bottom:8px;">'+
          '<img src="'+h.img+'" style="width:100%;display:block;">'+
          '<div style="display:flex;align-items:center;gap:6px;padding:6px 9px;border-top:1px solid #eef2f0;">'+
            '<span style="flex:1;font-size:8px;color:#8b9590;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">Ảnh đơn · '+esc(h.text||'')+'</span>'+
            '<span data-mg-save="'+i+'" style="flex-shrink:0;font-size:8.5px;color:#2f8a7a;border:1px solid #bfd8d0;border-radius:6px;padding:2px 7px;cursor:pointer;">Lưu</span>'+
            '<span data-mg-del="'+i+'" style="flex-shrink:0;font-size:8.5px;color:#c84632;border:1px solid #e6c0b8;border-radius:6px;padding:2px 7px;cursor:pointer;">Xóa</span>'+
          '</div></div>';
