        // ★ Phái sinh phương tiện: gán ổn định cho mỗi nhân vật một “phương tiện lên mạng” (normal/borrowed/messenger/offline), làm nguồn cảm giác phương tiện và xung đột
        var _hseed = 0, _c; for (var _i = 0; _i < name.length; _i++) { _c = name.charCodeAt(_i); _hseed = (_hseed * 31 + _c) >>> 0; }
