      if (_cgCanManageGroup() && who && who !== 'Tôi' && who !== (_groupState || {}).owner) {
        var _isMuted = (_groupState && _groupState.muted && _groupState.muted.indexOf(who) >= 0);
        _mh += '<div class="cdp-lmi" onclick="' + (_isMuted ? '_cgUnmuteMember' : '_cgMuteMember') + '(\'' + (_phEscape(who).replace(/'/g, '\\\'')) + '\');_cgCloseGMenu()"><i class="fa-solid fa-microphone-slash"></i> ' + (_isMuted ? 'Bỏ cấm nói' : 'Cấm nói') + '</div>';
        _mh += '<div class="cdp-lmi" onclick="_cgKickMember(\'' + (_phEscape(who).replace(/'/g, '\\\'')) + '\');_cgCloseGMenu()"><i class="fa-solid fa-user-slash"></i> Mời ra khỏi nhóm</div>';
      }
