    _groupCur.forEach(function (nm) { var r = _phFindRole(nm); if (r) playerCards += '【' + r.name + '】\n- Thân phận: ' + (r.tag || 'Người trong truyện') + '\n- Hảo cảm với chủ nhân: ' + r.aff + '\n- Nhật ký gần đây: ' + ((r.diaryTexts && r.diaryTexts.slice(-1)[0]) || 'Chưa có') + '\n- Phương tiện: ' + (r.mediumNote || 'Có điện thoại, gõ chữ bình thường') + '\n- Trạng thái: ' + (r.status || 'Trực tuyến') + '\n- Độ nhiệt tình khi nói: ' + Math.round((r.statusRate || 1) * 100) + '% (khi trạng thái tệ/đang tắm/mất ngủ có thể không trả lời hoặc trả lời chậm)\n\n'; });
