      + '<div style="display:flex;align-items:center;gap:10px;margin:6px 0 12px"><input type="number" id="cdpSetKeep" min="50" max="1000" value="' + (_st.keepMsgs || 200) + '" style="flex:1;padding:6px;font-size:13px;background:var(--panel2,#f7f8fa);border:1px solid var(--line,#dfe3e7);border-radius:8px;color:var(--ink1,#2e3337)"><span style="font-size:10px;color:#8b95a1">tin / chat riêng và chat nhóm giữ riêng</span></div>'
